template <typename T>
void execute_policy(T value) {
    if constexpr (std::is_integral_v<T>) {
        // Only compiled if T is an integer type
        value *= 5;
    } else if constexpr (std::is_floating_point_v<T>) {
        // Only compiled if T is a float type
        value += 1.0;
    } else {
        static_assert(false, "Unsupported type.");
    }
}

int a = 10;
execute_policy(a);  // Compiler selects and generates integer code path.

double b = 3.14;
execute_policy(b);  // Compiler selects and generates float code path.

// No runtime branch overhead (if/else eliminated at compile time).
